// ===== Configuração de segurança (edite aqui) =====
const CONFIG = {
  // Máximo de chamadas por minuto a este webhook (o excedente recebe HTTP 429).
  limitePorMinuto: 60,
  // Se preenchidas, valem no lugar das pastas enviadas pelo app (caminho, ex.: /Causa/Documentos).
  pastaDestinoFixa: '',
  pastaImportacaoFixa: '',
};
// ==================================================

// Proteções comuns aos webhooks do Causa (embutidas no início do nó "Validar pedido").
// CONFIG é definido logo abaixo, no próprio nó: ajuste ali os valores do seu escritório.

// Limite de requisições por minuto, contado no n8n (os dados estáticos do workflow
// só são gravados em execuções de produção, ou seja, com o workflow ativo).
const limitarTaxa = () => {
  const estado = $getWorkflowStaticData('global');
  const agora = Date.now();
  estado.chamadas = (Array.isArray(estado.chamadas) ? estado.chamadas : []).filter((t) => agora - t < 60_000);
  if (estado.chamadas.length >= CONFIG.limitePorMinuto) return false;
  estado.chamadas.push(agora);
  return true;
};

// Campos de mesclagem: objeto simples, chaves curtas, valores de texto com tamanho limitado.
const validarCampos = (campos) => {
  if (!campos || typeof campos !== 'object' || Array.isArray(campos)) return 'Campos de mesclagem inválidos.';
  const entradas = Object.entries(campos);
  if (entradas.length === 0) return 'Nenhum campo para mesclar.';
  if (entradas.length > 100) return 'Campos demais (máximo 100).';
  for (const [chave, valor] of entradas) {
    if (!/^[\w.]{1,60}$/.test(chave)) return `Nome de campo inválido: ${chave.slice(0, 60)}`;
    if (valor != null && typeof valor !== 'string' && typeof valor !== 'number') return `Valor inválido no campo ${chave}.`;
    if (String(valor ?? '').length > 10_000) return `Valor grande demais no campo ${chave}.`;
  }
  return null;
};

const muitasRequisicoes = () => [
  { json: { rota: 'limite', resposta: { erro: 'Muitas requisições ao n8n. Aguarde um minuto e tente de novo.' } } },
];

// Valida o pedido do app Causa e decide a rota. No OneDrive, modelos e pastas
// são caminhos a partir da raiz do seu OneDrive, como "/Causa/Modelos/Procuracao.docx".
if (!limitarTaxa()) return muitasRequisicoes();
const corpo = $input.first().json.body ?? {};
const acao = String(corpo.acao ?? '');
const GRAPH = 'https://graph.microsoft.com/v1.0/me/drive';
const erro = (mensagem) => [{ json: { rota: 'erro', resposta: { erro: mensagem } } }];

// Caminho absoluto, sem "..", sem caracteres proibidos no OneDrive.
const ehCaminho = (v) =>
  typeof v === 'string' && /^\/[^"*:<>?\\|#%]*$/.test(v) && !v.split('/').some((p) => p === '..' || p === '.');
const codificar = (caminho) =>
  caminho.split('/').filter(Boolean).map(encodeURIComponent).join('/');
const itemDoCaminho = (caminho) => (codificar(caminho) ? `${GRAPH}/root:/${codificar(caminho)}:` : `${GRAPH}/root`);

if (acao === 'ping') {
  return [{ json: { rota: 'ping', resposta: { ok: true, versao: 1, provedor: 'onedrive' } } }];
}

if (acao === 'listar_arquivos') {
  const pasta = CONFIG.pastaImportacaoFixa || (corpo.pastaId ? String(corpo.pastaId) : '/');
  if (!ehCaminho(pasta)) return erro('Caminho de pasta inválido. Use algo como /Causa/Documentos.');
  const busca = String(corpo.busca ?? '').trim().slice(0, 100);
  const campos = '$select=id,name,webUrl,file,folder,lastModifiedDateTime&$top=100';
  const url = busca
    ? `${itemDoCaminho(pasta)}/search(q='${encodeURIComponent(busca.replace(/'/g, "''"))}')?${campos}`
    : `${itemDoCaminho(pasta)}/children?${campos}`;
  return [{ json: { rota: 'listar_arquivos', url } }];
}

if (acao === 'gerar_documento') {
  const { modeloId, nomeArquivo, campos } = corpo;
  const pastaId = CONFIG.pastaDestinoFixa || corpo.pastaId;
  if (!ehCaminho(modeloId) || !/\.docx$/i.test(modeloId)) {
    return erro('O modelo deve ser o caminho de um arquivo .docx no OneDrive, como /Causa/Modelos/Procuracao.docx.');
  }
  if (!ehCaminho(pastaId)) return erro('Caminho da pasta de destino inválido. Use algo como /Causa/Documentos.');
  if (typeof nomeArquivo !== 'string' || !nomeArquivo.trim()) return erro('Informe o nome do arquivo.');
  const camposInvalidos = validarCampos(campos);
  if (camposInvalidos) return erro(camposInvalidos);

  const nome = `${nomeArquivo.trim().replace(/[\\/"*:<>?|#%]/g, '-').slice(0, 200)}.docx`;
  const destino = `${pastaId.replace(/\/+$/, '')}/${nome}`;
  return [{
    json: {
      rota: 'gerar_documento',
      urlModelo: `${itemDoCaminho(modeloId)}/content`,
      urlDestino: `${itemDoCaminho(destino)}/content?@microsoft.graph.conflictBehavior=rename`,
      nome,
      campos,
    },
  }];
}

return erro(`Ação desconhecida: ${acao.slice(0, 40) || '(vazia)'}`);

const arquivos = ($input.first().json.value ?? [])
  .filter((f) => !f.folder)
  .sort((a, b) => String(b.lastModifiedDateTime).localeCompare(String(a.lastModifiedDateTime)))
  .slice(0, 50)
  .map((f) => ({
    id: f.id,
    nome: f.name,
    url: f.webUrl,
    mimeType: f.file?.mimeType ?? '',
    modificadoEm: f.lastModifiedDateTime,
  }));
return [{ json: { resposta: { arquivos } } }];

// O nó Compression só abre arquivos com extensão .zip, e um .docx é um zip.
const item = $input.first();
item.binary.modelo.fileName = 'modelo.zip';
item.binary.modelo.fileExtension = 'zip';
item.binary.modelo.mimeType = 'application/zip';
return [item];

/**
 * Preenche campos {{chave}} no XML de um documento do Word (word/document.xml,
 * cabeçalhos e rodapés). O Word costuma quebrar um mesmo campo em vários
 * trechos <w:t> (por correção ortográfica, formatação etc.), então a busca é
 * feita no texto de cada parágrafo inteiro e só o conteúdo dos <w:t> é
 * reescrito: as tags do documento nunca são alteradas, só o texto delas.
 *
 * Este arquivo é embutido no workflow do OneDrive pelo gerar-workflows.mjs e
 * também é testado pelo Jest do app.
 */

const CAMPO = /\{\{\s*([\w.]+)\s*\}\}/g;
const TRECHO = /<w:t(\s[^>]*)?>([\s\S]*?)<\/w:t>/g;
const PARAGRAFO = /<w:p[\s>][\s\S]*?<\/w:p>/g;

function desescapar(texto) {
  return texto
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&');
}

function escapar(texto) {
  return texto.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function mesclarParagrafo(paragrafo, campos) {
  const trechos = [];
  for (const m of paragrafo.matchAll(TRECHO)) trechos.push(desescapar(m[2]));
  const completo = trechos.join('');
  if (!completo.includes('{{')) return paragrafo;

  // Dono de cada caractere do texto completo (índice do trecho <w:t>).
  const dono = [];
  trechos.forEach((t, i) => {
    for (let k = 0; k < t.length; k++) dono.push(i);
  });

  const substituicoes = new Map();
  for (const m of completo.matchAll(CAMPO)) {
    if (Object.prototype.hasOwnProperty.call(campos, m[1])) {
      substituicoes.set(m.index, { fim: m.index + m[0].length, valor: String(campos[m[1]] ?? '') });
    }
  }
  if (substituicoes.size === 0) return paragrafo;

  // O valor entra no trecho onde o campo começa; o resto do campo some dos outros trechos.
  const novos = trechos.map(() => '');
  for (let i = 0; i < completo.length; ) {
    const s = substituicoes.get(i);
    if (s) {
      novos[dono[i]] += s.valor.replace(/\r?\n/g, ' ');
      i = s.fim;
    } else {
      novos[dono[i]] += completo[i];
      i++;
    }
  }

  let indice = 0;
  return paragrafo.replace(TRECHO, (_, atributos = '', original) => {
    const texto = novos[indice++];
    if (texto === desescapar(original)) return `<w:t${atributos}>${original}</w:t>`;
    const preservar = /xml:space=/.test(atributos) ? atributos : `${atributos} xml:space="preserve"`;
    return `<w:t${preservar}>${escapar(texto)}</w:t>`;
  });
}

function mesclarXmlWord(xml, campos) {
  return xml.replace(PARAGRAFO, (p) => mesclarParagrafo(p, campos));
}

/** Partes do .docx que podem conter campos. */
function ehParteComTexto(caminho) {
  return /^word\/(document|header\d*|footer\d*|footnotes|endnotes)\.xml$/.test(caminho);
}


// Preenche os campos nas partes de texto do .docx e devolve o caminho completo
// de cada parte no nome do arquivo, para o nó Compression remontar o zip.
// mesclarXmlWord e ehParteComTexto vêm de codigo/mesclarDocx.js.
const item = $input.first();
const campos = $('Validar pedido').first().json.campos;
const partes = [];
for (const [chave, binario] of Object.entries(item.binary ?? {})) {
  const caminho = binario.directory ? `${binario.directory}/${binario.fileName}` : binario.fileName;
  if (ehParteComTexto(caminho)) {
    const xml = (await this.helpers.getBinaryDataBuffer(0, chave)).toString('utf8');
    const mesclado = mesclarXmlWord(xml, campos);
    item.binary[chave] = await this.helpers.prepareBinaryData(Buffer.from(mesclado, 'utf8'), caminho, 'application/xml');
  }
  item.binary[chave].fileName = caminho;
  delete item.binary[chave].directory;
  partes.push(chave);
}
if (!partes.some((p) => item.binary[p].fileName === 'word/document.xml')) {
  throw new Error('O arquivo de modelo não parece ser um documento do Word (.docx).');
}
item.json = { partes: partes.join(',') };
return [item];

const enviado = $input.first().json;
return [{
  json: {
    resposta: {
      arquivo: {
        id: enviado.id,
        nome: enviado.name,
        url: enviado.webUrl,
        mimeType: enviado.file?.mimeType ?? 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      },
    },
  },
}];

const SERVICO = {"nome":"O OneDrive","dica404":"Confira o caminho do modelo e da pasta (ex.: /Causa/Modelos/Procuracao.docx) na conta Microsoft conectada ao n8n.","dica403":"Verifique a credencial Microsoft Drive no n8n e se ela tem permissão Files.ReadWrite.All."};
// Transforma a falha da API do Google ou da Microsoft em uma mensagem para o app.
// SERVICO ({ nome, dica404, dica403 }) é definido no topo pelo gerar-workflows.mjs.
const item = $input.first().json;
const e = item.error ?? item;
const codigo = String(e.httpCode ?? e.status ?? '');
// O corpo de erro ({"error":{"message":...}}) pode vir embutido e escapado na mensagem.
const extrair = (texto) => {
  if (typeof texto !== 'string') return '';
  const json = texto.slice(texto.indexOf('{'), texto.lastIndexOf('}') + 1);
  for (const candidato of [texto, json, json.replace(/\\"/g, '"')]) {
    try {
      const valor = JSON.parse(candidato);
      if (valor && valor.error && valor.error.message) return valor.error.message;
    } catch (e) {}
  }
  return '';
};
const detalhe = extrair(e.description) || extrair(e.message) || e.message || 'erro desconhecido';
let dica = '';
if (codigo === '404') dica = ` ${SERVICO.dica404}`;
if (codigo === '401' || codigo === '403') dica = ` ${SERVICO.dica403}`;
return [{ json: { resposta: { erro: `${SERVICO.nome} recusou o pedido (${codigo || 'sem código'}): ${detalhe.replace(/\.+$/, '')}.${dica}` } } }];
